// Only tickets with this label are work orders for Claude: ready_label in the data table codebot_settings
const READY_LABEL = String($('[Work] Settings').all().map(i => i.json).find(r => r.key === 'ready_label')?.value ?? '').trim() || 'ready-for-agent';
// Open predecessors: native GitHub dependencies, or else a line "Blocked by: #1, #2" in the issue text
const openBlockers = (i, openSet) => {
  const native = (i.blockedBy?.nodes || []).filter(b => b.state === 'OPEN').map(b => b.number);
  const line = (String(i.body || '').match(/^\s*Blocked by:\s*(.+)$/im) || [])[1] || '';
  const fromBody = [...line.matchAll(/#(\d+)/g)].map(m => Number(m[1])).filter(n => openSet.has(n));
  return [...new Set([...native, ...fromBody])];
};
// Parent issues are not work orders, even if they carry the label.
// Recognised by sub-issues, or by an open issue naming them as its parent (natively or in the text).
const parentRef = i => {
  if (i.parent?.number) return i.parent.number;
  const b = String(i.body || '');
  const m = b.match(/^##\s*Parent\s*\n+[^\n]*?#(\d+)/im) || b.match(/^\s*(?:Parent|Part of)\b[^\n#]*#(\d+)/im);
  return m ? Number(m[1]) : null;
};
const r = $('[Work] Resolve repo').first().json;
const chat_id = $('[Work] Router').first().json.chat_id;
if (!r.repo) return [{ json: { has_issue: false, text: `No project "${r.arg}" in codebot_projects. /work shows the list.` } }];
const repoData = $input.first().json.data?.repository;
if (!repoData) return [{ json: { has_issue: false, text: `Repo "${r.repo}" not found (or no access).` } }];
const all = repoData.issues?.nodes || [];
const openSet = new Set(all.map(i => i.number));
const parents = new Set(all.map(parentRef).filter(Boolean));
const isParent = i => (i.subIssues?.totalCount || 0) > 0 || parents.has(i.number);
const ready = all.filter(i => (i.labels?.nodes || []).some(l => l.name === READY_LABEL) && !isParent(i));
// Open PR for the ticket: linked ("Closes #N") or branch claude/issue-<N>-…; draft PRs count too
const branchPrs = new Set((repoData.pullRequests?.nodes || [])
  .map(p => (String(p.headRefName || '').match(/^claude\/issue-(\d+)(?:-|$)/) || [])[1]).filter(Boolean).map(Number));
const hasOpenPr = i => branchPrs.has(i.number) || (i.closedByPullRequestsReferences?.nodes || []).some(p => p.state === 'OPEN');
const work = ready.filter(i => !hasOpenPr(i));
const inReview = ready.length - work.length;
if (!ready.length) return [{ json: { has_issue: false,
  text: `No tickets with the label ${READY_LABEL} in ${repoData.nameWithOwner}. A worker only starts tickets with this label.` } }];
if (!work.length) return [{ json: { has_issue: false,
  text: `All ${ready.length} tickets with the label ${READY_LABEL} in ${repoData.nameWithOwner} already have an open PR. Review and merge first:\nhttps://github.com/${repoData.nameWithOwner}/pulls` } }];
// Oldest issue whose predecessors are all closed
const idx = work.findIndex(i => !openBlockers(i, openSet).length);
if (idx < 0) return [{ json: { has_issue: false,
  text: `All ${work.length} tickets with the label ${READY_LABEL} in ${repoData.nameWithOwner} are waiting for open predecessors.` } }];
const i = work[idx];
const age = Math.floor((Date.now() - new Date(i.createdAt).getTime()) / 86400e3);
const body = (i.body || '').trim().slice(0, 600);
const labels = (i.labels?.nodes || []).map(l => l.name).join(', ');
const text = [
  `🗂 ${repoData.nameWithOwner}`,
  `Oldest startable ticket (${age} days old):`,
  `#${i.number} ${i.title}`,
  labels ? `Labels: ${labels}` : null,
  idx ? `Skipped: ${idx} older ticket(s) with open predecessors` : null,
  inReview ? `With an open PR, waiting for you: ${inReview}` : null,
  i.url,
  body ? `\n${body}${(i.body || '').length > 600 ? ' […]' : ''}` : null,
  '\nLet Claude work on it?',
].filter(Boolean).join('\n');
const cb = a => `w|${a}|${repoData.nameWithOwner}|${i.number}`;
return [{ json: { has_issue: true, text, payload: {
  chat_id, text, link_preview_options: { is_disabled: true },
  reply_markup: { inline_keyboard: [[
    { text: '✅ Yes, start', callback_data: cb('y') },
    { text: '❌ No', callback_data: cb('n') } ]] } } } }];

