parameters.jsCode:
// Find the PR for the issue: branch claude/issue-<N>-…, a linked issue, or "Closes #N" in the text
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const metas = $('[Start] Wait').all().map(i => i.json);
return $input.all().map((it, idx) => {
  const m = metas[idx];
  const n = m.issue_number;
  const since = new Date(m.started_at).getTime() - 5 * 60e3;
  const closes = new RegExp(`(close[sd]?|fix(e[sd])?|resolve[sd]?)\\s+#${n}\\b`, 'i');
  const branch = new RegExp(`^claude/issue-${n}(\\D|$)`);
  const prs = it.json.data?.repository?.pullRequests?.nodes;
  const head = `${esc(m.repo)}#${n}: ${esc(m.title)}`;
  const session = `<a href="${m.session_url}">Open session</a>`;
  if (!prs) return { json: { text: `⚠️ PR check for ${head} failed (GitHub unreachable).\n${session}` } };
  const pr = prs.find(p => new Date(p.createdAt).getTime() >= since && (
    branch.test(p.headRefName || '') ||
    (p.closingIssuesReferences?.nodes || []).some(x => x.number === n) ||
    closes.test(p.body || '')));
  if (!pr) return { json: { text: `⚠️ No PR for ${head}\nAfter 90 minutes there is no matching pull request.\n${session}` } };
  const state = pr.state === 'MERGED' ? 'merged' : pr.state === 'CLOSED' ? 'closed' : pr.isDraft ? 'draft, not finished yet' : 'ready for review';
  const gaps = String(pr.body || '').split(/\n(?=#{1,6}\s)/).find(s => /^#{1,6}\s*Gaps in the issue/i.test(s));
  const gapText = gaps ? gaps.replace(/^#{1,6}[^\n]*\n?/, '').trim().slice(0, 600) : '';
  return { json: { text: [
    `${pr.isDraft ? '📝' : '✅'} PR for ${head}`,
    `Status: ${state}`,
    `<a href="${pr.url}">PR #${pr.number}: ${esc(pr.title)}</a>`,
    gapText && !/^(none|-|–)\.?$/i.test(gapText) ? `\nGaps in the issue:\n${esc(gapText)}` : null,
  ].filter(Boolean).join('\n') } };
});

// Values from the data table codebot_settings
const setting = (k, fallback) => {
  const v = String($input.all().map(i => i.json).find(r => r.key === k)?.value ?? '').trim() || fallback;
  if (!v) throw new Error(`${k} is missing in codebot_settings`);
  return v;
};
const timezone = setting('timezone');
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`timezone in codebot_settings is not a valid IANA time zone: ${timezone}`);
// ==== ADJUST HERE ====
return [{ json: {
  CHAT_ID: setting('telegram_chat_id'),
  CALENDAR_ID: setting('calendar_id'),   // the events are created here
  TIMEZONE: timezone,

  DEADLINE_DAYS: 45,                    // deadlines within this period go into the calendar

  // The orchestrator starts tickets with this label at Claude (CodeBot - Start Claude Routine).
  // The orchestrator ignores all other issues. CodeBot - Planning proposes planning sessions.
  CCR_LABEL: setting('ready_label', 'ready-for-agent'),
  MAX_CCR_PER_RUN: 3,                   // at most this many starts per run
}}];

const cfg = $('[Orchestrator] Config').first().json;
const tz = cfg.TIMEZONE;
const now = DateTime.now().setZone(tz);
const events = $('[Orchestrator] Calendar: Events').all().map(i => i.json).filter(e => e.id && e.status !== 'cancelled');
const rows = $('[Orchestrator] Projects').all().map(i => i.json).filter(r => r.key);
// Open issues of the repos in codebot_projects
const items = ($('[Orchestrator] GitHub').first().json.data?.search?.nodes || [])
  .filter(c => c && c.number && c.__typename === 'Issue')
  .map(c => ({ content: c }));

// Open predecessors: native GitHub dependencies, or else a line "Blocked by: #1, #2" in the issue text
const openBlockers = (i, openSet) => {
  const native = (i.blockedBy?.nodes || []).filter(b => b.state === 'OPEN').map(b => b.number);
  const line = (String(i.body || '').match(/^\s*Blocked by:\s*(.+)$/im) || [])[1] || '';
  const fromBody = [...line.matchAll(/#(\d+)/g)].map(m => Number(m[1])).filter(n => openSet.has(n));
  return [...new Set([...native, ...fromBody])];
};
// Open PRs per repo, recognised by the branch claude/issue-<N>-… (in addition to the link through "Closes #N")
const branchPrs = {};
for (const r of Object.values($('[Orchestrator] GitHub').first().json.data || {})) {
  if (!r?.nameWithOwner) continue;
  branchPrs[r.nameWithOwner.toLowerCase()] = new Set((r.pullRequests?.nodes || [])
    .map(p => (String(p.headRefName || '').match(/^claude\/issue-(\d+)(?:-|$)/) || [])[1]).filter(Boolean).map(Number));
}
const eventKey = e => (String(e.description || '').match(/codebot-key:\s*(\S+)/) || [])[1] || null;
const existingKeys = new Set(events.map(eventKey).filter(Boolean));

// --- Projects from codebot_projects
const prioVal = { High: 3, Medium: 2, Low: 1 };
const projects = rows.map(r => ({
  key: r.key, current: r.next_block || null, name: r.name,
  repo: String(r.repo || '').trim().toLowerCase(), prio: r.priority || 'Medium', status: r.status,
  deadline: /^\d{4}-\d{2}-\d{2}/.test(String(r.deadline || '')) ? String(r.deadline) : null }));
const byRepo = Object.fromEntries(projects.filter(p => p.repo).map(p => [p.repo, p]));
const inactive = p => p && ['Paused', 'Done', 'Someday'].includes(p.status);

// --- Candidates from the open issues
const ccr = [];
const openByRepo = {};
for (const it of items) (openByRepo[it.content.repository.nameWithOwner.toLowerCase()] ||= new Set()).add(it.content.number);
for (const it of items) {
  const c = it.content;
  if (!c || c.state !== 'OPEN' || !c.repository) continue;
  const labels = (c.labels?.nodes || []).map(l => l.name);
  const repo = c.repository.nameWithOwner;
  const proj = byRepo[repo.toLowerCase()];
  if (!proj || inactive(proj)) continue;
  let score = prioVal[proj?.prio] || 1;
  if (proj?.deadline && DateTime.fromISO(proj.deadline).diff(now, 'days').days < 14) score += 3;
  if (labels.includes(cfg.CCR_LABEL)) {
    // Ticket for Claude: start only without an open PR and without open predecessors
    const hasPr = (c.closedByPullRequestsReferences?.nodes || []).some(p => p.state === 'OPEN')
      || (branchPrs[repo.toLowerCase()] || new Set()).has(c.number);
    const blocked = openBlockers(c, openByRepo[repo.toLowerCase()] || new Set()).length > 0;
    if (!hasPr && !blocked) ccr.push({ repo, issue: c, score });
    continue;
  }
  // Everything else (no label or a different one) is ignored.
}

const out = [];

// --- Deadlines from codebot_projects: all-day event + advance warning 3 days before
const allDay = (date, summary, description, key) => ({ json: {
  kind: 'event', key,
  label: `${date.setLocale('en').toFormat('ccc d LLL')} ${summary}`,
  summary, description: `${description}\ncodebot-key: ${key}`,
  start: date.set({ hour: 12 }).toISO(), end: date.plus({ days: 1 }).set({ hour: 12 }).toISO(),
  allday: 'yes', showMeAs: 'transparent',
} });
const today = now.startOf('day');
for (const p of projects) {
  if (!p.deadline || inactive(p)) continue;
  const date = DateTime.fromISO(p.deadline, { zone: tz }).startOf('day');
  const left = date.diff(today, 'days').days;
  if (left < 0 || left > cfg.DEADLINE_DAYS) continue;
  const key = `codebot-deadline:${p.key}:${date.toISODate()}`;
  if (!existingKeys.has(key)) out.push(allDay(date, `⏰ Deadline: ${p.name}`, 'Deadline from the project list.', key));
  const pre = date.minus({ days: 3 });
  const preKey = `codebot-deadline-pre:${p.key}:${date.toISODate()}`;
  if (pre >= today && !existingKeys.has(preKey))
    out.push(allDay(pre, `⏰ In 3 days: deadline ${p.name}`, `Deadline on ${date.toFormat('yyyy-MM-dd')}.`, preKey));
}
// --- Write the next planning session per project (from the calendar, scheduled through CodeBot - Planning) back to codebot_projects
const next = {};
const addBlock = (key, iso) => {
  const m = String(key || '').match(/^codebot-(?:issue|plan):([^#\s]+)/);
  const proj = m && byRepo[m[1].toLowerCase()];
  if (!proj) return;
  const d = DateTime.fromISO(iso).setZone(tz);
  if (d <= now) return;
  if (!next[proj.key] || d < next[proj.key].d) next[proj.key] = { d, proj };
};
for (const e of events) if (e.start?.dateTime) addBlock(eventKey(e), e.start.dateTime);
for (const { d, proj } of Object.values(next)) {
  const cur = proj.current ? DateTime.fromISO(proj.current).setZone(tz) : null;
  if (cur && Math.abs(cur.diff(d, 'minutes').minutes) < 1) continue; // unchanged
  out.push({ json: { kind: 'block', key: proj.key, date: d.toISO(), project: proj.name } });
}
// --- Jobs for Claude (the double-start guard lives in CodeBot - Start Claude Routine)
for (const w of ccr.sort((a, b) => b.score - a.score).slice(0, cfg.MAX_CCR_PER_RUN)) {
  out.push({ json: { kind: 'ccr', repo: w.repo, issue_number: w.issue.number, title: w.issue.title,
                     url: w.issue.url, body: w.issue.body || '', source: 'dev-orchestrator' } });
}
return out;

// Query GitHub only for the repos in codebot_projects (no account-wide search)
const rows = $('[Orchestrator] Projects').all().map(i => i.json).filter(r => r.key);
const repos = [...new Set(rows.map(r => String(r.repo || '').trim()).filter(r => /^[\w.-]+\/[\w.-]+$/.test(r)))];
if (!repos.length) return [{ json: { query: 'query { viewer { login } }', repos } }];
const repoParts = repos.map((r, i) => {
  const [o, n] = r.split('/');
  return `  r${i}: repository(owner: "${o}", name: "${n}") { nameWithOwner pushedAt pullRequests(states: OPEN, first: 50) { nodes { number headRefName } } }`;
});
const q = `is:open is:issue archived:false ${repos.map(r => 'repo:' + r).join(' ')}`;
const query = `query {
${repoParts.join('\n')}
  search(type: ISSUE, first: 100, query: "${q}") {
    nodes {
      ... on Issue { __typename number title url state body repository { nameWithOwner } labels(first: 10) { nodes { name } } blockedBy(first: 20) { nodes { number state } } closedByPullRequestsReferences(first: 5) { nodes { number state } } }
    }
  }
}`;
return [{ json: { query, repos } }];

// Values from the data table codebot_settings
const setting = (k, fallback) => {
  const v = String($input.all().map(i => i.json).find(r => r.key === k)?.value ?? '').trim() || fallback;
  if (!v) throw new Error(`${k} is missing in codebot_settings`);
  return v;
};
const timezone = setting('timezone');
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`timezone in codebot_settings is not a valid IANA time zone: ${timezone}`);
// ==== ADJUST HERE ====
return [{ json: {
  CHAT_ID: setting('telegram_chat_id'),
  TIMEZONE: timezone,

  THRESHOLD: 3,                          // ask from this score upwards
  MIN_HOURS_BETWEEN_PINGS: 18,           // at most one question within this period
  NEXT_BLOCK_SKIP_DAYS: 5,               // don't nudge projects that have a block within the next X days

  // When may it ask? (hours, end exclusive)
  WEEKDAY_FROM: 18, WEEKDAY_TO: 22,
  WEEKEND_FROM: 9,  WEEKEND_TO: 21,
}}];

const cfg = $('[Sweep] Config').first().json;
const now = DateTime.now().setZone(cfg.TIMEZONE);
const weekend = now.weekday >= 6;
const [from, to] = weekend ? [cfg.WEEKEND_FROM, cfg.WEEKEND_TO] : [cfg.WEEKDAY_FROM, cfg.WEEKDAY_TO];
return now.hour >= from && now.hour < to ? $input.all() : [];

const cfg = $('[Sweep] Config').first().json;
const tz = cfg.TIMEZONE;
const now = DateTime.now().setZone(tz);
const rows = $('[Sweep] Projects').all().map(i => i.json).filter(r => r.key);
// Read the GitHub response: r0, r1, … = repos (last push), search = open issues and PRs
const gh = $('[Sweep] GitHub').first().json.data || null;
const pushed = {};
for (const [k, v] of Object.entries(gh || {})) if (/^r\d+$/.test(k) && v) pushed[v.nameWithOwner.toLowerCase()] = DateTime.fromISO(v.pushedAt);
const date = s => { const dt = s ? DateTime.fromISO(String(s), { zone: tz }) : null; return dt && dt.isValid ? dt : null; };
const days = dt => dt ? now.diff(dt, 'days').days : null;

const openByRepo = {};
for (const i of gh?.search?.nodes || []) {
  if (!i?.repository) continue;
  (openByRepo[i.repository.nameWithOwner.toLowerCase()] ||= []).push({
    number: i.number, title: i.title, pr: i.__typename === 'PullRequest', updated: i.updatedAt,
    labels: (i.labels?.nodes || []).map(l => l.name) });
}

const projects = rows.map(r => ({
  name: r.name, key: r.key, status: r.status, group: r.group || null, prio: r.priority || 'Medium',
  repo: String(r.repo || '').trim().toLowerCase(), quiet_days: r.quiet_days ?? null, deadline: date(r.deadline),
  waitingFor: r.waiting_for || '', waitingSince: date(r.waiting_since),
  nextStep: r.next_step || '', description: r.description || '',
  checkin: date(r.last_checkin), ping: date(r.last_ping), block: date(r.next_block),
})).filter(p => !['Done', 'Paused'].includes(p.status));

// Global brake: at most one question per MIN_HOURS_BETWEEN_PINGS
const lastPing = projects.map(p => p.ping).filter(Boolean).sort((a, b) => b - a)[0];
if (lastPing && now.diff(lastPing, 'hours').hours < cfg.MIN_HOURS_BETWEEN_PINGS) return [];

const prioFactor = { High: 1.5, Medium: 1, Low: 0.7 };
const scored = [];

for (const p of projects) {
  const someday = p.status === 'Someday';
  const quiet = p.quiet_days || (someday ? 30 : 7);
  if (p.ping && days(p.ping) < quiet / 2) continue;                          // not the same project too often
  if (p.block && p.block > now && p.block.diff(now, 'days').days <= cfg.NEXT_BLOCK_SKIP_DAYS) continue; // work is already scheduled

  const reasons = [];
  let score = 0;
  const act = [pushed[p.repo], p.checkin].filter(Boolean).sort((a, b) => b - a)[0] || null;
  const quietDays = act ? days(act) : quiet * 2;
  if (quietDays > quiet) {
    score += 2 + (quietDays - quiet) / quiet;
    reasons.push(act ? `no activity for ${Math.round(quietDays)} days` : 'never had a check-in or commit');
  }
  if (p.status === 'Waiting' && p.waitingSince && days(p.waitingSince) > 5) {
    score += 2; reasons.push(`waiting for ${Math.round(days(p.waitingSince))} days on: ${p.waitingFor || 'unknown'}`);
  }
  if (p.deadline && !someday) {
    const left = -days(p.deadline);
    if (left < 0) { score += 3; reasons.push('deadline passed'); }
    else if (left < 14) { score += 1 + (14 - left) / 4; reasons.push(`deadline in ${Math.round(left)} days`); }
  }
  const open = openByRepo[p.repo] || [];
  const stalePRs = open.filter(i => i.pr && days(DateTime.fromISO(i.updated)) > 5);
  if (stalePRs.length) { score += 1; reasons.push(`${stalePRs.length} PR(s) without movement`); }

  score *= prioFactor[p.prio] || 1;
  score *= 0.8 + Math.random() * 0.4; // a bit of randomness
  if (score >= cfg.THRESHOLD) scored.push({ ...p, score: Math.round(score * 10) / 10, reasons, open: open.slice(0, 10) });
}

if (!scored.length) return [];
scored.sort((a, b) => b.score - a.score);
const t = scored[0];
const iso = dt => dt ? dt.toISODate() : null;
return [{ json: { ...t, deadline: iso(t.deadline), waitingSince: iso(t.waitingSince), checkin: iso(t.checkin),
                  ping: iso(t.ping), block: iso(t.block) } }];

parameters.text:
=You are my personal project manager. I am a software developer and look after several software projects.

Write ONE short, specific question about the following project: at most 3 sentences, in English, informal, no greeting, no Markdown. Refer to the specific reason and the last known state. No reproach; be curious and helpful instead.
If the status is "Someday", don't ask about progress; ask whether I want to activate the project in the coming weeks or keep it parked.

Project: {{ $json.name }}
Description: {{ $json.description || '-' }}
Status: {{ $json.status }} | Priority: {{ $json.prio }} | Group: {{ $json.group || '-' }}
Reason: {{ $json.reasons.join('; ') }}
Next step on file: {{ $json.nextStep || '-' }}
Waiting for: {{ $json.waitingFor || '-' }}
Open issues and PRs:
{{ $json.open.map(i => (i.number ? '#' + i.number + ' ' : '') + (i.pr ? '(PR) ' : '') + i.title + (i.labels?.length ? ' [' + i.labels.join(', ') + ']' : '')).join('\n') || 'none' }}

Reply with the message itself only.

parameters.jsCode:
// Query GitHub only for the repos in codebot_projects (no account-wide search)
const rows = $('[Sweep] Projects').all().map(i => i.json).filter(r => r.key);
const repos = [...new Set(rows.map(r => String(r.repo || '').trim()).filter(r => /^[\w.-]+\/[\w.-]+$/.test(r)))];
if (!repos.length) return [{ json: { query: 'query { viewer { login } }', repos } }];
const repoParts = repos.map((r, i) => {
  const [o, n] = r.split('/');
  return `  r${i}: repository(owner: "${o}", name: "${n}") { nameWithOwner pushedAt }`;
});
const q = `is:open archived:false ${repos.map(r => 'repo:' + r).join(' ')}`;
const query = `query {
${repoParts.join('\n')}
  search(type: ISSUE, first: 100, query: "${q}") {
    nodes {
      ... on Issue { __typename number title updatedAt repository { nameWithOwner } labels(first: 10) { nodes { name } } }
      ... on PullRequest { __typename number title url updatedAt repository { nameWithOwner } }
    }
  }
}`;
return [{ json: { query, repos } }];

// Rows that codebot_settings needs. Keys that already exist stay untouched, so the workflow can run again safely.
// Fill in the empty values in n8n under "Data tables" afterwards.
const ROWS = [
  { key: 'telegram_bot_token', value: '' },             // token of your bot from @BotFather
  { key: 'telegram_chat_id', value: '' },               // the only chat the system serves and writes to
  { key: 'calendar_id', value: '' },                    // calendar for deadlines and planning sessions
  { key: 'timezone', value: '' },                       // IANA time zone, e.g. Europe/Berlin
  { key: 'ready_label', value: 'ready-for-agent' },     // label that releases a ticket for a worker
];
const existing = new Set($input.all().map(i => i.json.key).filter(Boolean));
return ROWS.filter(r => !existing.has(r.key)).map(json => ({ json }));
